// Synthetic records for validation/export/persistence tests; never shipped or inserted automatically.
export function makeStory(count=10){return {id:'test-story',title:'测试故事',hook:'测试引子',bookId:'zhuangzi',theme:'人情冷暖',status:'published',pages:Array.from({length:count},(_,i)=>({caption:'测试旁白'+i,prompt:'A test scene '+i,image:'/api/media/test-'+i+'.png',audio:''})),reflection:'测试余味',sourceText:'用于测试的原文片段。',sourceUrl:'https://example.org/source',adaptationNote:'测试改编说明',checks:{source:true,plot:true,visual:true},actualCost:null,currency:'CNY',revision:1,createdAt:'2026-10-29T00:00:00Z',updatedAt:'2026-10-29T00:00:00Z'};}

export async function insertStory(app,story=makeStory()){const {stories}=await import('../../db/schema.ts');await app.services.db.insert(stories).values({...story,pages:JSON.stringify(story.pages),checks:JSON.stringify(story.checks)});return story;}
